/**
 * Shared board data model.
 *
 * Committed as contract - no task owns this file. Every module builds on these
 * shapes so a card produced by the store is a card the renderer can draw and a
 * card persistence can round-trip.
 */

export const BOARD_VERSION = 1

let seq = 0

/** Monotonic, collision-free within a page load. Not meant to be global. */
export function nextId(prefix) {
  seq += 1
  return `${prefix}_${seq.toString(36)}`
}

export function createCard(title, extra = {}) {
  return { id: nextId('card'), title, done: false, ...extra }
}

export function createList(title, cards = []) {
  return { id: nextId('list'), title, cards: cards.map((card) => ({ ...card })) }
}

export function createBoard(title = 'My board', lists = []) {
  return {
    version: BOARD_VERSION,
    title,
    lists: lists.map((list) => ({ ...list, cards: list.cards.map((card) => ({ ...card })) })),
  }
}

/** Deep copy. The store hands these out so callers cannot mutate its state. */
export function cloneBoard(board) {
  return {
    ...board,
    lists: board.lists.map((list) => ({ ...list, cards: list.cards.map((card) => ({ ...card })) })),
  }
}

/** Throws on anything the renderer or persistence could not handle. */
export function assertBoard(board) {
  if (!board || typeof board !== 'object') throw new TypeError('board must be an object')
  if (!Array.isArray(board.lists)) throw new TypeError('board.lists must be an array')
  for (const list of board.lists) {
    if (typeof list.id !== 'string') throw new TypeError('list.id must be a string')
    if (typeof list.title !== 'string') throw new TypeError('list.title must be a string')
    if (!Array.isArray(list.cards)) throw new TypeError('list.cards must be an array')
    for (const card of list.cards) {
      if (typeof card.id !== 'string') throw new TypeError('card.id must be a string')
      if (typeof card.title !== 'string') throw new TypeError('card.title must be a string')
      if (typeof card.done !== 'boolean') throw new TypeError('card.done must be a boolean')
    }
  }
  return board
}

/**
 * Test fixtures. Ids are hard-coded, not generated, so assertions stay stable
 * across tasks and across runs.
 */

export function sampleBoard() {
  return {
    version: 1,
    title: 'Sprint',
    lists: [
      {
        id: 'list_todo',
        title: 'To do',
        cards: [
          { id: 'card_a', title: 'Design tokens', done: false },
          { id: 'card_b', title: 'Write the store', done: false },
        ],
      },
      {
        id: 'list_doing',
        title: 'Doing',
        cards: [{ id: 'card_c', title: 'Drag and drop', done: false }],
      },
      {
        id: 'list_done',
        title: 'Done',
        cards: [{ id: 'card_d', title: 'Repo setup', done: true }],
      },
    ],
  }
}

export function emptyBoard() {
  return { version: 1, title: 'Empty', lists: [] }
}

/** Minimal stand-in for window.localStorage, for persistence tests. */
export function fakeStorage(initial = {}) {
  const data = new Map(Object.entries(initial))
  return {
    getItem: (key) => (data.has(key) ? data.get(key) : null),
    setItem: (key, value) => void data.set(key, String(value)),
    removeItem: (key) => void data.delete(key),
    get length() {
      return data.size
    },
  }
}

/**
 * Wiring only - no logic lives here.
 *
 * Committed as contract because every task would otherwise need to edit it. The
 * imports below are the exact signatures each task must ship; see
 * docs/pwa-contract.md for the table.
 */

import { createStore } from '../src/board/store.mjs'
import { renderBoard } from '../src/board/render.mjs'
import { attachDragAndDrop } from '../src/board/dnd.mjs'
import { loadBoard, saveBoard } from '../src/board/persist.mjs'
import { registerServiceWorker } from '../src/pwa/register.mjs'
import { sampleBoard } from '../src/board/fixtures.mjs'
import { MOUNT_ID } from '../src/board/dom-contract.mjs'

const mount = document.getElementById(MOUNT_ID)
const store = createStore(loadBoard(window.localStorage) ?? sampleBoard())

function paint() {
  mount.innerHTML = renderBoard(store.getBoard())
}

store.subscribe((board) => {
  saveBoard(window.localStorage, board)
  paint()
})

paint()

attachDragAndDrop(mount, {
  onMove: (cardId, toListId, toIndex) => store.moveCard(cardId, toListId, toIndex),
})

registerServiceWorker('./sw.mjs')

/**
 * Static file server, no dependencies.
 *
 * Rooted at the repo, not at public/, so public/app.mjs can import ../src/board/*.mjs
 * over HTTP. Run with `npm run serve`, then open http://localhost:4173.
 */

import { createServer } from 'node:http'
import { readFile } from 'node:fs/promises'
import { extname, join, normalize, sep } from 'node:path'

const ROOT = process.cwd()
const PORT = Number(process.env.PORT ?? 4173)

const TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
}

createServer(async (req, res) => {
  const { pathname } = new URL(req.url, 'http://localhost')
  const requested = pathname === '/' ? '/public/index.html' : decodeURIComponent(pathname)
  const file = join(ROOT, normalize(requested))

  if (!file.startsWith(ROOT + sep)) {
    res.writeHead(403, { 'content-type': 'text/plain' })
    return res.end('forbidden')
  }

  try {
    const body = await readFile(file)
    res.writeHead(200, {
      'content-type': TYPES[extname(file)] ?? 'application/octet-stream',
      'cache-control': 'no-store',
    })
    res.end(body)
  } catch {
    res.writeHead(404, { 'content-type': 'text/plain' })
    res.end('not found')
  }
}).listen(PORT, () => {
  console.log(`serving ${ROOT} on http://localhost:${PORT}`)
})

{
  "name": "todo-app-colab",
  "version": "0.1.0",
  "private": false,
  "description": "A small todo app used to test collaborative sessions",
  "type": "commonjs",
  "scripts": {
    "test": "node --test",
    "start": "node src/cli.js",
    "serve": "node scripts/serve.mjs"
  },
  "license": "MIT"
}

/**
 * Shared contract for the trello-style board.
 *
 * Every board task imports from this file and nothing in this file depends on
 * a task, so the tasks can be built in any order without touching each other.
 *
 * @typedef {Object} Column
 * @property {string} id     stable, kebab-case, used as the key in a snapshot
 * @property {string} title  human label, shown by the renderer
 *
 * @typedef {Object} Card
 * @property {string} id        unique across the whole board
 * @property {string} title
 * @property {string} columnId  id of the column the card currently sits in
 *
 * @typedef {Object} BoardSnapshot
 * @property {Column[]} columns                 in display order, left to right
 * @property {Record<string, Card[]>} cardsByColumn  keyed by column id, one
 *   entry per column (empty array when the column has no cards), each array in
 *   display order with index 0 at the top
 */

/**
 * The columns a board starts with when none are supplied.
 * @type {Column[]}
 */
const DEFAULT_COLUMNS = [
  { id: 'todo', title: 'To Do' },
  { id: 'doing', title: 'Doing' },
  { id: 'done', title: 'Done' },
]

/** Thrown when a column id does not exist on the board. */
const ERR_UNKNOWN_COLUMN = 'unknown-column'

/** Thrown when a card id does not exist on the board. */
const ERR_UNKNOWN_CARD = 'unknown-card'

/** The error every board operation throws on bad input. */
class BoardError extends Error {
  /**
   * @param {string} code one of ERR_UNKNOWN_COLUMN, ERR_UNKNOWN_CARD
   * @param {string} [message]
   */
  constructor(code, message) {
    super(message || code)
    this.name = 'BoardError'
    this.code = code
  }
}

let cardSeq = 0

/**
 * Allocates the next card id. Ids are opaque strings; never parse them.
 * @returns {string}
 */
function nextCardId() {
  cardSeq += 1
  return `card-${cardSeq}`
}

/**
 * Resets the card id counter. For tests that assert on exact ids.
 * @returns {void}
 */
function resetCardIds() {
  cardSeq = 0
}

module.exports = {
  DEFAULT_COLUMNS,
  ERR_UNKNOWN_COLUMN,
  ERR_UNKNOWN_CARD,
  BoardError,
  nextCardId,
  resetCardIds,
}

/**
 * Shared contract for the trello-style board.
 *
 * Every board task imports from this file and nothing in this file depends on
 * a task, so the tasks can be built in any order without touching each other.
 *
 * @typedef {Object} Column
 * @property {string} id     stable, kebab-case, used as the key in a snapshot
 * @property {string} title  human label, shown by the renderer
 *
 * @typedef {Object} Card
 * @property {string} id        unique across the whole board
 * @property {string} title
 * @property {string} columnId  id of the column the card currently sits in
 *
 * @typedef {Object} BoardSnapshot
 * @property {Column[]} columns                      in display order, top to bottom
 * @property {Record<string, Card[]>} cardsByColumn  keyed by column id, one entry
 *   per column (empty array when the column has no cards), each array in display
 *   order with index 0 at the top
 */

/**
 * The columns a board starts with when none are supplied.
 * @type {Column[]}
 */
const DEFAULT_COLUMNS = [
  { id: 'todo', title: 'To Do' },
  { id: 'doing', title: 'Doing' },
  { id: 'done', title: 'Done' },
]

/** A column id that does not exist on the board. */
const ERR_UNKNOWN_COLUMN = 'unknown-column'

/** A card id that does not exist on the board. */
const ERR_UNKNOWN_CARD = 'unknown-card'

/** The error every board operation throws on bad input. */
class BoardError extends Error {
  /**
   * @param {string} code one of ERR_UNKNOWN_COLUMN, ERR_UNKNOWN_CARD
   * @param {string} [message]
   */
  constructor(code, message) {
    super(message || code)
    this.name = 'BoardError'
    this.code = code
  }
}

let cardSeq = 0

/**
 * Allocates the next card id. Ids are opaque strings; never parse them.
 * @returns {string}
 */
function nextCardId() {
  cardSeq += 1
  return `card-${cardSeq}`
}

/**
 * Resets the card id counter, for tests that assert on exact ids.
 * @returns {void}
 */
function resetCardIds() {
  cardSeq = 0
}

module.exports = {
  DEFAULT_COLUMNS,
  ERR_UNKNOWN_COLUMN,
  ERR_UNKNOWN_CARD,
  BoardError,
  nextCardId,
  resetCardIds,
}

/**
 * The store's public surface, written down so it can be checked.
 *
 * `src/lib/board/store.js` (task board-store) must export `createBoard(columns?)`
 * returning an object that satisfies `assertBoardApi`, whose `snapshot()`
 * satisfies `assertSnapshotShape`. Behaviour the shape cannot capture:
 *
 * - `addCard(columnId, title)` -> Card. Appends to the BOTTOM of that column
 *   with an id from `nextCardId()`. Throws BoardError(ERR_UNKNOWN_COLUMN) when
 *   the column does not exist.
 * - `moveCard(cardId, toColumnId, toIndex)` -> Card. Lifts the card out of its
 *   current column, then inserts it into `toColumnId` at `toIndex`, where index
 *   0 is the top. `toIndex` is optional and defaults to the bottom of the
 *   target column. An index past the end clamps to the bottom, a negative index
 *   clamps to the top. A move within one column is a reorder, with the target
 *   position computed AFTER the card has been lifted out. Throws
 *   BoardError(ERR_UNKNOWN_CARD) for an unknown card, and
 *   BoardError(ERR_UNKNOWN_COLUMN) for an unknown target column.
 * - `removeCard(cardId)` -> boolean. True when a card was removed, false when
 *   the id was not on the board. Never throws.
 * - Every getter returns copies: mutating a returned snapshot, card, or array
 *   must never change the board.
 */

const BOARD_METHODS = ['snapshot', 'addCard', 'moveCard', 'removeCard']

/**
 * Throws a TypeError unless `board` looks like a store built by createBoard.
 * @param {unknown} board
 * @returns {void}
 */
function assertBoardApi(board) {
  if (!board || typeof board !== 'object') {
    throw new TypeError('board: expected an object')
  }
  for (const method of BOARD_METHODS) {
    if (typeof board[method] !== 'function') {
      throw new TypeError(`board.${method}: expected a function`)
    }
  }
}

/**
 * Throws a TypeError unless `snapshot` matches the BoardSnapshot typedef:
 * an array of columns, and one cardsByColumn array per column id, each card
 * carrying the id of the column it is filed under.
 * @param {unknown} snapshot
 * @returns {void}
 */
function assertSnapshotShape(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') {
    throw new TypeError('snapshot: expected an object')
  }
  const { columns, cardsByColumn } = /** @type {any} */ (snapshot)
  if (!Array.isArray(columns)) {
    throw new TypeError('snapshot.columns: expected an array')
  }
  if (!cardsByColumn || typeof cardsByColumn !== 'object') {
    throw new TypeError('snapshot.cardsByColumn: expected an object')
  }
  for (const column of columns) {
    if (typeof column.id !== 'string' || typeof column.title !== 'string') {
      throw new TypeError('snapshot.columns[]: expected { id, title } strings')
    }
    const cards = cardsByColumn[column.id]
    if (!Array.isArray(cards)) {
      throw new TypeError(`snapshot.cardsByColumn['${column.id}']: expected an array`)
    }
    for (const card of cards) {
      if (typeof card.id !== 'string' || typeof card.title !== 'string') {
        throw new TypeError('card: expected { id, title } strings')
      }
      if (card.columnId !== column.id) {
        throw new TypeError(`card ${card.id}: columnId '${card.columnId}' does not match column '${column.id}'`)
      }
    }
  }
  const extra = Object.keys(cardsByColumn).filter((id) => !columns.some((c) => c.id === id))
  if (extra.length > 0) {
    throw new TypeError(`snapshot.cardsByColumn: no such column(s): ${extra.join(', ')}`)
  }
}

module.exports = { BOARD_METHODS, assertBoardApi, assertSnapshotShape }

/**
 * Primitives for the board's plain-text format.
 *
 * `src/components/board/render.js` (task board-render) must export
 * `renderBoard(snapshot)` built from exactly these pieces: one section per
 * column in `snapshot.columns` order, sections joined by a blank line, no
 * trailing newline. A column with no cards is the single line
 * EMPTY_COLUMN_LINE. A board with no columns is EMPTY_BOARD_LINE.
 *
 *     == To Do (2) ==
 *     - card-1 try session-share
 *     - card-2 split this app
 *
 *     == Doing (0) ==
 *     (empty)
 */

/** Rendered for a column that has no cards. */
const EMPTY_COLUMN_LINE = '(empty)'

/** Rendered for a board that has no columns at all. */
const EMPTY_BOARD_LINE = 'Empty board.'

/** Separates one column section from the next. */
const SECTION_SEPARATOR = '\n\n'

/**
 * @param {import('../../lib/board/contract.js').Column} column
 * @param {number} cardCount
 * @returns {string}
 */
function columnHeader(column, cardCount) {
  return `== ${column.title} (${cardCount}) ==`
}

/**
 * @param {import('../../lib/board/contract.js').Card} card
 * @returns {string}
 */
function cardLine(card) {
  return `- ${card.id} ${card.title}`
}

module.exports = {
  EMPTY_COLUMN_LINE,
  EMPTY_BOARD_LINE,
  SECTION_SEPARATOR,
  columnHeader,
  cardLine,
}

/**
 * Shared contract for dragging and dropping board cards.
 *
 * Every drag task imports from this file and nothing in this file depends on a
 * task, so the tasks can be built in any order without touching each other.
 *
 * @typedef {Object} DropTarget
 * @property {string} columnId  id of the column the card would land in
 * @property {number} index     insertion index AFTER the dragged card has been
 *   lifted out of its column. This is the same convention `store.moveCard`
 *   already uses for `toIndex`: index 0 is the top, and the position is
 *   computed on the column as it looks WITHOUT the dragged card. A drop is
 *   therefore always `board.moveCard(cardId, over.columnId, over.index)`.
 *
 * @typedef {Object} DragState
 * @property {string|null} cardId        the card being dragged, null when idle
 * @property {string|null} fromColumnId  the column the drag started in
 * @property {DropTarget|null} over      where the card would land right now
 */

const {
  BoardError,
  ERR_UNKNOWN_CARD,
  ERR_UNKNOWN_COLUMN,
} = require('./contract.js')

/** A drag operation was asked for while no drag is in progress. */
const ERR_NO_ACTIVE_DRAG = 'no-active-drag'

/** A drag was started while another drag was still in progress. */
const ERR_DRAG_IN_PROGRESS = 'drag-in-progress'

/** A drop was asked for before the drag was ever hovered over a column. */
const ERR_NO_DROP_TARGET = 'no-drop-target'

/**
 * The error every drag operation throws on bad input. Unknown ids keep using
 * BoardError, so callers see one error type per kind of mistake: a bad id is a
 * BoardError, a bad sequence of drag calls is a DragError.
 */
class DragError extends Error {
  /**
   * @param {string} code one of ERR_NO_ACTIVE_DRAG, ERR_DRAG_IN_PROGRESS, ERR_NO_DROP_TARGET
   * @param {string} [message]
   */
  constructor(code, message) {
    super(message || code)
    this.name = 'DragError'
    this.code = code
  }
}

/**
 * The state of a board with no drag in progress. Frozen: call `idleDrag()` when
 * you need a value you can hand out.
 * @type {Readonly<DragState>}
 */
const IDLE_DRAG = Object.freeze({ cardId: null, fromColumnId: null, over: null })

/**
 * A fresh idle DragState, safe to hand to a caller.
 * @returns {DragState}
 */
function idleDrag() {
  return { cardId: null, fromColumnId: null, over: null }
}

/**
 * True when a card is currently being dragged.
 * @param {DragState|null|undefined} state
 * @returns {boolean}
 */
function isDragging(state) {
  return Boolean(state && state.cardId)
}

module.exports = {
  ERR_NO_ACTIVE_DRAG,
  ERR_DRAG_IN_PROGRESS,
  ERR_NO_DROP_TARGET,
  DragError,
  IDLE_DRAG,
  idleDrag,
  isDragging,
  // re-exported so a drag task has one import for the errors it can throw
  BoardError,
  ERR_UNKNOWN_CARD,
  ERR_UNKNOWN_COLUMN,
}

/**
 * The drag controller's public surface, written down so it can be checked.
 *
 * `src/lib/board/dnd.js` (task dnd-controller) must export
 * `createDragController(board)`, where `board` is a store from
 * `src/lib/board/store.js`, returning an object that satisfies
 * `assertControllerApi`, whose `state()` satisfies `assertDragState`.
 * Behaviour the shape cannot capture:
 *
 * - `state()` -> DragState. A copy: mutating it must never change the
 *   controller. Idle is `{ cardId: null, fromColumnId: null, over: null }`.
 * - `beginDrag(cardId)` -> DragState. Picks the card up and records the column
 *   it came from; `over` starts null. Throws BoardError(ERR_UNKNOWN_CARD) when
 *   the card is not on the board, and DragError(ERR_DRAG_IN_PROGRESS) when a
 *   drag is already in progress. The board itself is NOT changed by picking a
 *   card up: `board.snapshot()` is identical before and after.
 * - `dragOver(columnId, index)` -> DragState. Records where the card would
 *   land. `index` counts the target column WITHOUT the dragged card in it (the
 *   DropTarget convention), so the valid range is 0..N where N is the number of
 *   cards in that column that are not the dragged card. `index` is optional and
 *   defaults to N, the bottom. An index past N clamps to N, a negative index
 *   clamps to 0. Throws DragError(ERR_NO_ACTIVE_DRAG) when idle and
 *   BoardError(ERR_UNKNOWN_COLUMN) when the column does not exist. Calling it
 *   again replaces the previous target.
 * - `drop()` -> Card. Commits with `board.moveCard(cardId, over.columnId,
 *   over.index)`, then returns to idle, returning the moved card. Throws
 *   DragError(ERR_NO_ACTIVE_DRAG) when idle and DragError(ERR_NO_DROP_TARGET)
 *   when no `dragOver` has been recorded; in both cases the board is unchanged.
 * - `cancelDrag()` -> boolean. True when a drag was in progress, false when
 *   already idle. Returns to idle and leaves the board exactly as it was.
 *   Never throws.
 */

const DRAG_METHODS = ['state', 'beginDrag', 'dragOver', 'drop', 'cancelDrag']

/**
 * Throws a TypeError unless `controller` looks like one built by
 * createDragController.
 * @param {unknown} controller
 * @returns {void}
 */
function assertControllerApi(controller) {
  if (!controller || typeof controller !== 'object') {
    throw new TypeError('controller: expected an object')
  }
  for (const method of DRAG_METHODS) {
    if (typeof controller[method] !== 'function') {
      throw new TypeError(`controller.${method}: expected a function`)
    }
  }
}

/**
 * Throws a TypeError unless `state` matches the DragState typedef: a card id
 * and a source column that are both set or both null, and either no drop
 * target or one naming a column and a non-negative integer index.
 * @param {unknown} state
 * @returns {void}
 */
function assertDragState(state) {
  if (!state || typeof state !== 'object') {
    throw new TypeError('state: expected an object')
  }
  const { cardId, fromColumnId, over } = /** @type {any} */ (state)
  if (cardId !== null && typeof cardId !== 'string') {
    throw new TypeError('state.cardId: expected a string or null')
  }
  if (fromColumnId !== null && typeof fromColumnId !== 'string') {
    throw new TypeError('state.fromColumnId: expected a string or null')
  }
  if ((cardId === null) !== (fromColumnId === null)) {
    throw new TypeError('state: cardId and fromColumnId must be set together')
  }
  if (over === undefined) {
    throw new TypeError('state.over: expected a drop target or null')
  }
  if (over === null) return
  if (typeof over !== 'object') {
    throw new TypeError('state.over: expected a drop target or null')
  }
  if (typeof over.columnId !== 'string') {
    throw new TypeError('state.over.columnId: expected a string')
  }
  if (!Number.isInteger(over.index) || over.index < 0) {
    throw new TypeError('state.over.index: expected a non-negative integer')
  }
  if (cardId === null) {
    throw new TypeError('state.over: expected null while idle')
  }
}

module.exports = { DRAG_METHODS, assertControllerApi, assertDragState }

/**
 * Shared contract for the browser board.
 *
 * The server (src/web/server.js) and the page (src/web/public/) both import
 * this file and neither imports the other, so the two can be built in any
 * order. Nothing here reaches for the DOM or for node, so the same module
 * loads in a browser via <script> and in node via require.
 *
 * @typedef {Object} MovePayload
 * @property {string} cardId        card being dragged
 * @property {string} toColumnId    column it is dropped on
 * @property {number} [toIndex]     position within that column, 0 at the top;
 *   omitted means append to the end
 *
 * @typedef {Object} AddCardPayload
 * @property {string} columnId
 * @property {string} title
 */

/** Port `npm run web` listens on when PORT is not set. */
const DEFAULT_PORT = 4173

/**
 * The whole HTTP surface. Every response body is a BoardSnapshot as JSON
 * (see src/lib/board/contract.js) except errors, which are { error: code }.
 */
const ROUTES = {
  /** GET -> BoardSnapshot */
  snapshot: '/api/board',
  /** POST MovePayload -> BoardSnapshot */
  move: '/api/board/move',
  /** POST AddCardPayload -> BoardSnapshot */
  addCard: '/api/board/cards',
}

/**
 * Attributes the markup carries and the drag layer reads. The page owns its
 * markup, but these names are fixed so the drag logic can find cards and
 * columns without knowing how the page is laid out.
 */
const DATA_ATTR = {
  /** on a draggable card element, value is Card.id */
  card: 'data-card-id',
  /** on a column drop target, value is Column.id */
  column: 'data-column-id',
}

/** Request body was not shaped like the route expects. */
const ERR_BAD_PAYLOAD = 'bad-payload'

/** No route matched the method and path. */
const ERR_NOT_FOUND = 'not-found'

/** Thrown by the payload parsers; the server turns it into a 400. */
class PayloadError extends Error {
  /** @param {string} message */
  constructor(message) {
    super(message)
    this.name = 'PayloadError'
    this.code = ERR_BAD_PAYLOAD
  }
}

function requireString(value, field) {
  if (typeof value !== 'string' || value === '') {
    throw new PayloadError(`${field} must be a non-empty string`)
  }
  return value
}

/**
 * Validates a decoded move request body.
 * @param {unknown} value
 * @returns {MovePayload}
 * @throws {PayloadError}
 */
function parseMovePayload(value) {
  if (value === null || typeof value !== 'object') {
    throw new PayloadError('body must be an object')
  }
  const cardId = requireString(value.cardId, 'cardId')
  const toColumnId = requireString(value.toColumnId, 'toColumnId')
  if (value.toIndex === undefined || value.toIndex === null) {
    return { cardId, toColumnId }
  }
  if (!Number.isInteger(value.toIndex) || value.toIndex < 0) {
    throw new PayloadError('toIndex must be a non-negative integer')
  }
  return { cardId, toColumnId, toIndex: value.toIndex }
}

/**
 * Validates a decoded add-card request body.
 * @param {unknown} value
 * @returns {AddCardPayload}
 * @throws {PayloadError}
 */
function parseAddCardPayload(value) {
  if (value === null || typeof value !== 'object') {
    throw new PayloadError('body must be an object')
  }
  return {
    columnId: requireString(value.columnId, 'columnId'),
    title: requireString(value.title, 'title'),
  }
}

const api = {
  DEFAULT_PORT,
  ROUTES,
  DATA_ATTR,
  ERR_BAD_PAYLOAD,
  ERR_NOT_FOUND,
  PayloadError,
  parseMovePayload,
  parseAddCardPayload,
}

// Loads as a CommonJS module in node and as a global in the browser.
if (typeof module !== 'undefined' && module.exports) {
  module.exports = api
} else if (typeof globalThis !== 'undefined') {
  globalThis.boardWebContract = api
}

